     1→// Package ast defines the Abstract Syntax Tree for FV 2.0
     2→package ast
     3→
     4→// Program represents the root AST node
     5→type Program struct {
     6→	Definitions []Definition
     7→	MainBody    []Statement
     8→}
     9→
    10→// Definition represents top-level declarations
    11→type Definition interface {
    12→	definitionNode()
    13→}
    14→
    15→// FunctionDef represents a function definition
    16→type FunctionDef struct {
    17→	Name       string
    18→	Parameters []Parameter
    19→	ReturnType *Type
    20→	Body       []Statement
    21→}
    22→
    23→func (*FunctionDef) definitionNode() {}
    24→
    25→// TypeDef represents a type definition
    26→type TypeDef struct {
    27→	Name   string
    28→	Fields []Field
    29→}
    30→
    31→func (*TypeDef) definitionNode() {}
    32→
    33→// StructDef represents a struct definition
    34→type StructDef struct {
    35→	Name   string
    36→	Fields []Field
    37→}
    38→
    39→func (*StructDef) definitionNode() {}
    40→
    41→// InterfaceDef represents an interface definition
    42→type InterfaceDef struct {
    43→	Name    string
    44→	Methods []MethodSig
    45→}
    46→
    47→func (*InterfaceDef) definitionNode() {}
    48→
    49→// EnumDef represents an enum definition
    50→type EnumDef struct {
    51→	Name     string
    52→	Variants []EnumVariant
    53→}
    54→
    55→func (*EnumDef) definitionNode() {}
    56→
    57→// ExternDef represents an extern function declaration
    58→type ExternDef struct {
    59→	Name       string
    60→	Parameters []Parameter
    61→	ReturnType *Type
    62→	Library    string // optional library name from @link annotation
    63→}
    64→
    65→func (*ExternDef) definitionNode() {}
    66→
    67→// ImportStatement represents an import declaration
    68→type ImportStatement struct {
    69→	Module string // module name like "stdio", "math", etc.
    70→}
    71→
    72→func (*ImportStatement) definitionNode() {}
    73→
    74→// Parameter represents a function parameter
    75→type Parameter struct {
    76→	Name string
    77→	Type *Type
    78→}
    79→
    80→// Field represents a struct/type field
    81→type Field struct {
    82→	Name      string
    83→	Type      *Type
    84→	Mutable   bool
    85→	Default   Expression
    86→}
    87→
    88→// MethodSig represents a method signature
    89→type MethodSig struct {
    90→	Name       string
    91→	Parameters []Parameter
    92→	ReturnType *Type
    93→}
    94→
    95→// EnumVariant represents an enum variant
    96→type EnumVariant struct {
    97→	Name  string
    98→	Types []Type
    99→}
   100→
   101→// Statement represents a statement
   102→type Statement interface {
   103→	statementNode()
   104→}
   105→
   106→// LetStatement represents a let binding
   107→type LetStatement struct {
   108→	Name    string
   109→	Type    *Type
   110→	Init    Expression
   111→	Mutable bool
   112→}
   113→
   114→func (*LetStatement) statementNode() {}
   115→
   116→// ConstStatement represents a const binding
   117→type ConstStatement struct {
   118→	Name  string
   119→	Type  *Type
   120→	Value Expression
   121→}
   122→
   123→func (*ConstStatement) statementNode() {}
   124→
   125→// IfStatement represents an if/else statement
   126→type IfStatement struct {
   127→	Condition Expression
   128→	ThenBody  []Statement
   129→	ElseBody  []Statement
   130→}
   131→
   132→func (*IfStatement) statementNode() {}
   133→
   134→// ForStatement represents a for loop
   135→type ForStatement struct {
   136→	Variable string
   137→	Iterator Expression
   138→	Body     []Statement
   139→}
   140→
   141→func (*ForStatement) statementNode() {}
   142→
   143→// ForRangeStatement represents a for range loop
   144→type ForRangeStatement struct {
   145→	Variable string
   146→	Start    Expression
   147→	End      Expression
   148→	Body     []Statement
   149→}
   150→
   151→func (*ForRangeStatement) statementNode() {}
   152→
   153→// MatchStatement represents a match expression
   154→type MatchStatement struct {
   155→	Expression Expression
   156→	Arms       []MatchArm
   157→}
   158→
   159→func (*MatchStatement) statementNode() {}
   160→
   161→// MatchArm represents a match arm
   162→type MatchArm struct {
   163→	Pattern Pattern
   164→	Body    []Statement
   165→}
   166→
