     1→// Package parser implements V-compatible syntax parsing
     2→package parser
     3→
     4→import (
     5→	"fmt"
     6→	"strconv"
     7→
     8→	"fv2-lang/internal/ast"
     9→	"fv2-lang/internal/lexer"
    10→)
    11→
    12→// Parser converts tokens to AST
    13→type Parser struct {
    14→	tokens   []lexer.Token
    15→	pos      int
    16→	errors   []string
    17→}
    18→
    19→// New creates a new parser
    20→func New(tokens []lexer.Token) *Parser {
    21→	return &Parser{
    22→		tokens: tokens,
    23→		pos:    0,
    24→		errors: []string{},
    25→	}
    26→}
    27→
    28→// Parse parses tokens into an AST (with error recovery)
    29→func (p *Parser) Parse() (*ast.Program, error) {
    30→	var definitions []ast.Definition
    31→	var mainBody []ast.Statement
    32→
    33→	for !p.isAtEnd() {
    34→		if p.match(lexer.TknEof) {
    35→			break
    36→		}
    37→
    38→		// Handle import statements
    39→		if p.check(lexer.TknImport) {
    40→			def, err := p.parseImportStatement()
    41→			if err != nil {
    42→				p.errors = append(p.errors, err.Error())
    43→				p.synchronize()
    44→				continue
    45→			}
    46→			if def != nil {
    47→				definitions = append(definitions, def)
    48→			}
    49→		} else if p.check(lexer.TknExtern) {
    50→			// Handle extern function declaration
    51→			def, err := p.parseExternDef()
    52→			if err != nil {
    53→				p.errors = append(p.errors, err.Error())
    54→				p.synchronize()
    55→				continue
    56→			}
    57→			if def != nil {
    58→				definitions = append(definitions, def)
    59→			}
    60→		} else if p.check(lexer.TknFn) {
    61→			// Handle regular function definition
    62→			def, err := p.parseFunctionDef()
    63→			if err != nil {
    64→				p.errors = append(p.errors, err.Error())
    65→				p.synchronize() // Error recovery: skip to next definition
    66→				continue
    67→			}
    68→			if def != nil {
    69→				definitions = append(definitions, def)
    70→			}
    71→		} else if p.check(lexer.TknType) {
    72→			def, err := p.parseTypeDef()
    73→			if err != nil {
    74→				p.errors = append(p.errors, err.Error())
    75→				p.synchronize() // Error recovery
    76→				continue
    77→			}
    78→			if def != nil {
    79→				definitions = append(definitions, def)
    80→			}
    81→		} else if p.check(lexer.TknStruct) {
    82→			def, err := p.parseStructDef()
    83→			if err != nil {
    84→				p.errors = append(p.errors, err.Error())
    85→				p.synchronize() // Error recovery
    86→				continue
    87→			}
    88→			if def != nil {
    89→				definitions = append(definitions, def)
    90→			}
    91→		} else {
    92→			stmt, err := p.parseStatement()
    93→			if err != nil {
    94→				p.errors = append(p.errors, err.Error())
    95→				p.synchronize() // Error recovery
    96→				continue
    97→			}
    98→			if stmt != nil {
    99→				mainBody = append(mainBody, stmt)
   100→			}
   101→		}
   102→	}
   103→
   104→	// Return program even if there are errors (for partial parsing)
   105→	if len(p.errors) > 0 {
   106→		return &ast.Program{
   107→			Definitions: definitions,
   108→			MainBody:    mainBody,
   109→		}, fmt.Errorf("parse errors: %v", p.errors)
   110→	}
   111→
   112→	return &ast.Program{
   113→		Definitions: definitions,
   114→		MainBody:    mainBody,
   115→	}, nil
   116→}
