   118→// parseFunctionDef parses a function definition
   119→func (p *Parser) parseFunctionDef() (*ast.FunctionDef, error) {
   120→	if !p.match(lexer.TknFn) {
   121→		return nil, nil
   122→	}
   123→
   124→	name := p.current().Text
   125→	if !p.match(lexer.TknIdentifier) {
   126→		return nil, fmt.Errorf("expected function name at %d:%d", p.current().Line, p.current().Column)
   127→	}
   128→
   129→	if !p.match(lexer.TknLParen) {
   130→		return nil, fmt.Errorf("expected '(' at %d:%d", p.current().Line, p.current().Column)
   131→	}
   132→
   133→	// Parse parameters
   134→	var params []ast.Parameter
   135→	if !p.check(lexer.TknRParen) {
   136→		for {
   137→			paramName := p.current().Text
   138→			if !p.match(lexer.TknIdentifier) {
   139→				return nil, fmt.Errorf("expected parameter name at %d:%d", p.current().Line, p.current().Column)
   140→			}
   141→
   142→			var paramType *ast.Type
   143→			if p.match(lexer.TknColon) {
   144→				// Type annotation
   145→				paramType = p.parseType()
   146→			}
   147→
   148→			params = append(params, ast.Parameter{
   149→				Name: paramName,
   150→				Type: paramType,
   151→			})
   152→
   153→			if !p.match(lexer.TknComma) {
   154→				break
   155→			}
   156→		}
   157→	}
   158→
   159→	if !p.match(lexer.TknRParen) {
   160→		return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   161→	}
   162→
   163→	// Parse return type (V syntax: type directly after params, no ->)
   164→	var returnType *ast.Type
   165→	if !p.check(lexer.TknLBrace) && !p.isAtEnd() {
   166→		// Look ahead to see if next is a type (identifier or keyword type)
   167→		if p.check(lexer.TknIdentifier) || p.isPrimitiveType() {
   168→			returnType = p.parseType()
   169→		}
   170→	}
   171→
   172→	// Parse body
   173→	if !p.match(lexer.TknLBrace) {
   174→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   175→	}
   176→
   177→	var body []ast.Statement
   178→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   179→		stmt, err := p.parseStatement()
   180→		if err != nil {
   181→			return nil, err
   182→		}
   183→		if stmt != nil {
   184→			body = append(body, stmt)
   185→		}
   186→	}
   187→
   188→	if !p.match(lexer.TknRBrace) {
   189→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   190→	}
   191→
   192→	return &ast.FunctionDef{
   193→		Name:       name,
   194→		Parameters: params,
   195→		ReturnType: returnType,
   196→		Body:       body,
   197→	}, nil
   198→}
