   200→// parseTypeDef parses a type definition
   201→// V syntax: type UserId = i64
   202→func (p *Parser) parseTypeDef() (*ast.TypeDef, error) {
   203→	if !p.match(lexer.TknType) {
   204→		return nil, nil
   205→	}
   206→
   207→	name := p.current().Text
   208→	if !p.match(lexer.TknIdentifier) {
   209→		return nil, fmt.Errorf("expected type name at %d:%d", p.current().Line, p.current().Column)
   210→	}
   211→
   212→	if !p.match(lexer.TknAssign) {
   213→		return nil, fmt.Errorf("expected '=' at %d:%d", p.current().Line, p.current().Column)
   214→	}
   215→
   216→	// Parse the underlying type (simple type alias)
   217→	underlyingType := p.parseType()
   218→
   219→	return &ast.TypeDef{
   220→		Name: name,
   221→		Fields: []ast.Field{
   222→			{
   223→				Name: "value",
   224→				Type: underlyingType,
   225→			},
   226→		},
   227→	}, nil
   228→}
