   280→// parseStatement parses a statement
   281→func (p *Parser) parseStatement() (ast.Statement, error) {
   282→	if p.match(lexer.TknLet) {
   283→		return p.parseLetStatement()
   284→	}
   285→	if p.match(lexer.TknConst) {
   286→		return p.parseConstStatement()
   287→	}
   288→	if p.match(lexer.TknIf) {
   289→		return p.parseIfStatement()
   290→	}
   291→	if p.match(lexer.TknFor) {
   292→		return p.parseForStatement()
   293→	}
   294→	if p.match(lexer.TknMatch) {
   295→		return p.parseMatchStatement()
   296→	}
   297→	if p.match(lexer.TknReturn) {
   298→		return p.parseReturnStatement()
   299→	}
   300→	if p.match(lexer.TknLBrace) {
   301→		return p.parseBlockStatement()
   302→	}
   303→
   304→	// Assignment statement: ident = expr  or  ident.field = expr
   305→	if p.check(lexer.TknIdentifier) {
   306→		savedPos := p.pos
   307→		name := p.current().Text
   308→		p.advance()
   309→		if p.match(lexer.TknAssign) {
   310→			val, err := p.parseExpression()
   311→			if err != nil {
   312→				return nil, err
   313→			}
   314→			p.match(lexer.TknSemicolon)
   315→			return &ast.AssignStatement{Name: name, Value: val}, nil
   316→		}
   317→		// Not assignment, backtrack
   318→		p.pos = savedPos
   319→	}
   320→
   321→	// Expression statement
   322→	expr, err := p.parseExpression()
   323→	if err != nil {
   324→		return nil, err
   325→	}
   326→
   327→	// Consume optional semicolon
   328→	p.match(lexer.TknSemicolon)
   329→
   330→	return &ast.ExpressionStatement{Expression: expr}, nil
   331→}
