   339→		return nil, fmt.Errorf("expected variable name at %d:%d", p.current().Line, p.current().Column)
   340→	}
   341→
   342→	var varType *ast.Type
   343→	if p.match(lexer.TknColon) {
   344→		varType = p.parseType()
   345→	}
   346→
   347→	var init ast.Expression
   348→	if p.match(lexer.TknAssign) || p.match(lexer.TknColonAssign) {
   349→		var err error
   350→		init, err = p.parseExpression()
   351→		if err != nil {
   352→			return nil, err
   353→		}
   354→	}
   355→
   356→	p.match(lexer.TknSemicolon)
   357→
   358→	return &ast.LetStatement{
   359→		Name:    name,
   360→		Type:    varType,
   361→		Init:    init,
   362→		Mutable: isMutable,
   363→	}, nil
   364→}
