   464→	if !p.match(lexer.TknIn) {
   465→		return nil, fmt.Errorf("expected 'in' at %d:%d", p.current().Line, p.current().Column)
   466→	}
   467→
   468→	iter, err := p.parseExpression()
   469→	if err != nil {
   470→		return nil, err
   471→	}
   472→
   473→	if !p.match(lexer.TknLBrace) {
   474→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   475→	}
   476→
   477→	var body []ast.Statement
   478→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   479→		stmt, err := p.parseStatement()
   480→		if err != nil {
   481→			return nil, err
   482→		}
   483→		if stmt != nil {
   484→			body = append(body, stmt)
   485→		}
   486→	}
   487→
   488→	if !p.match(lexer.TknRBrace) {
   489→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   490→	}
