   492→	// Check if iter is a range (BinaryExpression with .. operator)
   493→	if binExpr, ok := iter.(*ast.BinaryExpression); ok && binExpr.Operator == ".." {
   494→		return &ast.ForRangeStatement{
   495→			Variable: varName,
   496→			Start:    binExpr.Left,
   497→			End:      binExpr.Right,
   498→			Body:     body,
   499→		}, nil
   500→	}
