   516→	if !p.match(lexer.TknLBrace) {
   517→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   518→	}
   519→
   520→	var arms []ast.MatchArm
   521→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   522→		// Parse pattern
   523→		pattern, err := p.parsePattern()
   524→		if err != nil {
   525→			return nil, err
   526→		}
   527→
   528→		if !p.match(lexer.TknFatArrow) {
   529→			return nil, fmt.Errorf("expected '=>' at %d:%d", p.current().Line, p.current().Column)
   530→		}
   531→
   532→		// Parse body
   533→		var body []ast.Statement
   534→		if p.match(lexer.TknLBrace) {
   535→			for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   536→				stmt, err := p.parseStatement()
   537→				if err != nil {
   538→					return nil, err
   539→				}
   540→				if stmt != nil {
   541→					body = append(body, stmt)
   542→				}
   543→			}
   544→			if !p.match(lexer.TknRBrace) {
   545→				return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   546→			}
   547→		} else {
   548→			stmt, err := p.parseStatement()
   549→			if err != nil {
   550→				return nil, err
   551→			}
   552→			if stmt != nil {
   553→				body = append(body, stmt)
   554→			}
   555→		}
   556→
   557→		arms = append(arms, ast.MatchArm{
   558→			Pattern: pattern,
   559→			Body:    body,
   560→		})
   561→
   562→		if !p.match(lexer.TknComma) {
   563→			break
   564→		}
   565→	}
   566→
   567→	if !p.match(lexer.TknRBrace) {
   568→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   569→	}
   570→
   571→	return &ast.MatchStatement{
   572→		Expression: expr,
   573→		Arms:       arms,
   574→	}, nil
   575→}
