   619→// parseBinaryExpression parses binary expressions with precedence
   620→func (p *Parser) parseBinaryExpression(minPrec int) (ast.Expression, error) {
   621→	left, err := p.parseUnary()
   622→	if err != nil {
   623→		return nil, err
   624→	}
   625→
   626→	for {
   627→		if p.isAtEnd() || !p.isOperator(p.current().Type) {
   628→			break
   629→		}
   630→
   631→		op := p.current()
   632→		prec := getPrecedence(op.Type)
   633→		if prec < minPrec {
   634→			break
   635→		}
   636→
   637→		p.advance()
   638→
   639→		right, err := p.parseBinaryExpression(prec + 1)
   640→		if err != nil {
   641→			return nil, err
   642→		}
   643→
   644→		left = &ast.BinaryExpression{
   645→			Left:     left,
   646→			Operator: op.Text,
   647→			Right:    right,
   648→		}
   649→	}

