   436→func (c *Checker) inferBinaryOpType(left, right Type, op string) Type {
   437→	// Arithmetic operators
   438→	if op == "+" || op == "-" || op == "*" || op == "/" || op == "%" {
   439→		if !c.isNumeric(left) || !c.isNumeric(right) {
   440→			c.addError(0, 0, fmt.Sprintf("arithmetic operator %s requires numeric types", op))
   441→			return left
   442→		}
   443→		if !left.Equal(right) {
   444→			c.addError(0, 0, fmt.Sprintf("type mismatch: %s vs %s", left.TypeString(), right.TypeString()))
   445→		}
   446→		return left
   447→	}
   448→
   449→	// Comparison operators
   450→	if op == "==" || op == "!=" || op == "<" || op == ">" || op == "<=" || op == ">=" {
   451→		return &PrimitiveType{Name: "bool"}
   452→	}
   453→
   454→	// Logical operators
   455→	if op == "&&" || op == "||" {
   456→		if !left.Equal(&PrimitiveType{Name: "bool"}) {
   457→			c.addError(0, 0, "logical operator requires bool")
   458→		}
   459→		return &PrimitiveType{Name: "bool"}
   460→	}
   461→
   462→	return left
   463→}
