   650→	if t == nil {
   651→		return &PrimitiveType{Name: "none"}
   652→	}
   653→
   654→	if t.IsArray {
   655→		return &ArrayType{ElementType: c.astTypeToCheckerType(t.ElementType)}
   656→	}
   657→
   658→	// Check if this is a registered struct type
   659→	sym := c.CurrentScope.Lookup(t.Name)
   660→	if sym != nil {
   661→		if st, ok := sym.Type.(*StructType); ok {
   662→			return st
   663→		}
   664→	}
   665→
   666→	return &PrimitiveType{Name: t.Name}
   667→}
