   369→// generateForStatement generates for loop
   370→func (g *Generator) generateForStatement(forStmt *ast.ForStatement) {
   371→	// for i in iterator -> convert to C for loop
   372→	// Handle array literals with known size vs. variables
   373→	var loopCondition string
   374→
   375→	if arrExpr, ok := forStmt.Iterator.(*ast.ArrayExpression); ok {
   376→		// Array literal with known size at compile time
   377→		loopCondition = fmt.Sprintf("_i < %d", len(arrExpr.Elements))
   378→	} else {
   379→		// Iterator is a variable - length must be provided at runtime
   380→		iterator := g.generateExpression(forStmt.Iterator)
   381→		loopCondition = fmt.Sprintf("_i < sizeof(%s)/sizeof(*%s)", iterator, iterator)
   382→		g.writeLine(fmt.Sprintf("// for %s in %s (array length calculation)", forStmt.Variable, iterator))
   383→	}
   384→
   385→	g.writeLine(fmt.Sprintf("for (int _i = 0; %s; _i++) {", loopCondition))
   386→	g.indent++
   387→
   388→	// Declare loop variable as array index
   389→	g.writeLine(fmt.Sprintf("int %s = _i;", forStmt.Variable))
   390→
   391→	// Loop body
   392→	for _, stmt := range forStmt.Body {
   393→		g.generateStatement(stmt)
   394→	}
   395→
   396→	g.indent--
   397→	g.writeLine("}")
   398→}
