   433→// generateMatchStatement generates match statement (as if-else chain)
   434→func (g *Generator) generateMatchStatement(match *ast.MatchStatement) {
   435→	// Convert match to if-else chain
   436→	expr := g.generateExpression(match.Expression)
   437→
   438→	for i, arm := range match.Arms {
   439→		// Generate pattern matching condition based on pattern type
   440→		var condition string
   441→
   442→		if arm.Pattern == nil {
   443→			// No pattern, always true
   444→			condition = "1"
   445→		} else {
   446→			// Type assert pattern to get correct type
   447→			switch p := arm.Pattern.(type) {
   448→			case *ast.LiteralPattern:
   449→				// Literal pattern: compare with expression
   450→				if p.Value != nil {
   451→					patternValue := g.generateExpression(p.Value)
   452→					condition = fmt.Sprintf("%s == %s", expr, patternValue)
   453→				} else {
   454→					condition = "1"
   455→				}
   456→			case *ast.IdentifierPattern:
   457→				// Identifier pattern: variable binding
   458→				// For now, treat as wildcard (would bind in full impl)
   459→				condition = "1"
   460→			case *ast.WildcardPattern:
   461→				// Wildcard: always matches (default case)
   462→				condition = "1"
   463→			default:
   464→				// Unknown pattern, treat as wildcard
   465→				condition = "1"
   466→			}
   467→		}
   468→
   469→		// Generate if/else if branch
   470→		if i == 0 {
   471→			g.writeLine(fmt.Sprintf("if (%s) {", condition))
   472→		} else {
   473→			g.writeLine(fmt.Sprintf("} else if (%s) {", condition))
   474→		}
   475→		g.indent++
   476→
   477→		for _, stmt := range arm.Body {
   478→			g.generateStatement(stmt)
   479→		}
   480→
   481→		g.indent--
   482→	}
   483→
   484→	if len(match.Arms) > 0 {
   485→		g.writeLine("}")
   486→	}
   487→}
