   502→// generateExpression generates C code for expression
   503→func (g *Generator) generateExpression(expr ast.Expression) string {
   504→	switch e := expr.(type) {
   505→	case *ast.IntegerLiteral:
   506→		return fmt.Sprintf("%d", e.Value)
   507→	case *ast.FloatLiteral:
   508→		// Format float with decimal point always visible
   509→		s := strconv.FormatFloat(e.Value, 'f', -1, 64)
   510→		if !strings.Contains(s, ".") {
   511→			s += ".0"
   512→		}
   513→		return s
   514→	case *ast.StringLiteral:
   515→		return fmt.Sprintf("\"%s\"", escapeString(e.Value))
   516→	case *ast.BoolLiteral:
   517→		if e.Value {
   518→			return "true"
   519→		}
   520→		return "false"
   521→	case *ast.NoneLiteral:
   522→		return "NULL"
   523→	case *ast.Identifier:
   524→		return e.Name
   525→	case *ast.BinaryExpression:
   526→		return g.generateBinaryExpression(e)
   527→	case *ast.UnaryExpression:
   528→		return g.generateUnaryExpression(e)
   529→	case *ast.CallExpression:
   530→		return g.generateCallExpression(e)
   531→	case *ast.ArrayExpression:
   532→		return g.generateArrayExpression(e)
   533→	case *ast.FieldExpression:
   534→		return g.generateFieldExpression(e)
   535→	case *ast.IndexExpression:
   536→		return g.generateIndexExpression(e)
   537→	case *ast.IfExpression:
   538→		return g.generateIfExpression(e)
   539→	case *ast.MethodCallExpression:
   540→		return g.generateMethodCallExpression(e)
   541→	case *ast.StructExpression:
   542→		return g.generateStructExpression(e)
   543→	case *ast.ErrorPropagation:
   544→		return g.generateExpression(e.Expression)
   545→	}
   546→
   547→	return "0"
   548→}
