   550→// generateBinaryExpression generates binary operation
   551→func (g *Generator) generateBinaryExpression(bin *ast.BinaryExpression) string {
   552→	left := g.generateExpression(bin.Left)
   553→	right := g.generateExpression(bin.Right)
   554→
   555→	switch bin.Operator {
   556→	case "..":
   557→		return fmt.Sprintf("range(%s, %s)", left, right)
   558→	case "==":
   559→		// string comparison: use strcmp
   560→		if g.isStringExpr(bin.Left) || g.isStringExpr(bin.Right) {
   561→			return fmt.Sprintf("(strcmp(%s, %s) == 0)", left, right)
   562→		}
   563→		return fmt.Sprintf("(%s == %s)", left, right)
   564→	case "!=":
   565→		if g.isStringExpr(bin.Left) || g.isStringExpr(bin.Right) {
   566→			return fmt.Sprintf("(strcmp(%s, %s) != 0)", left, right)
   567→		}
   568→		return fmt.Sprintf("(%s != %s)", left, right)
   569→	default:
   570→		return fmt.Sprintf("(%s %s %s)", left, bin.Operator, right)
   571→	}
   572→}
