   574→func (g *Generator) isStringExpr(expr ast.Expression) bool {
   575→	switch e := expr.(type) {
   576→	case *ast.StringLiteral:
   577→		return true
   578→	case *ast.Identifier:
   579→		if t, ok := g.varTypes[e.Name]; ok {
   580→			return t == "string"
   581→		}
   582→	case *ast.CallExpression:
   583→		if fnIdent, ok := e.Function.(*ast.Identifier); ok {
   584→			if t, ok := g.varTypes[fnIdent.Name+"_ret"]; ok {
   585→				return t == "string"
   586→			}
   587→		}
   588→	}
   589→	return false
   590→}
