   598→// generateCallExpression generates function call
   599→func (g *Generator) generateCallExpression(call *ast.CallExpression) string {
   600→	fn := g.generateExpression(call.Function)
   601→
   602→	var args []string
   603→	for _, arg := range call.Arguments {
   604→		args = append(args, g.generateExpression(arg))
   605→	}
   606→
   607→	// Handle builtin functions
   608→	if fnIdent, ok := call.Function.(*ast.Identifier); ok {
   609→		switch fnIdent.Name {
   610→		case "println":
   611→			if len(args) == 0 {
   612→				return `printf("\n")`
   613→			}
   614→			return g.generatePrintln(call.Arguments[0])
   615→		case "print":
   616→			if len(args) == 0 {
   617→				return `printf("")`
   618→			}
   619→			return g.generatePrint(call.Arguments[0])
   620→		case "len":
   621→			if len(args) == 1 {
   622→				return fmt.Sprintf(`(sizeof(%s)/sizeof(*%s))`, args[0], args[0])
   623→			}
   624→		case "abs":
   625→			if len(args) == 1 {
   626→				return fmt.Sprintf(`llabs(%s)`, args[0])
   627→			}
   628→		case "min":
   629→			if len(args) == 2 {
   630→				return fmt.Sprintf(`((%s) < (%s) ? (%s) : (%s))`, args[0], args[1], args[0], args[1])
   631→			}
   632→		case "max":
   633→			if len(args) == 2 {
   634→				return fmt.Sprintf(`((%s) > (%s) ? (%s) : (%s))`, args[0], args[1], args[0], args[1])
   635→			}
   636→		case "to_int":
   637→			if len(args) == 1 {
   638→				return fmt.Sprintf(`((long long)%s)`, args[0])
   639→			}
   640→		case "to_float":
   641→			if len(args) == 1 {
   642→				return fmt.Sprintf(`((double)%s)`, args[0])
   643→			}
   644→		// ── string 내장 함수 ──
   645→		case "str_len":
   646→			if len(args) == 1 {
   647→				return fmt.Sprintf(`((long long)strlen(%s))`, args[0])
   648→			}
   649→		case "str_at":
   650→			if len(args) == 2 {
   651→				return fmt.Sprintf(`((long long)(unsigned char)(%s)[%s])`, args[0], args[1])
   652→			}
   653→		case "str_eq":
   654→			if len(args) == 2 {
   655→				return fmt.Sprintf(`(strcmp(%s,%s)==0)`, args[0], args[1])
   656→			}
   657→		case "str_concat":
   658→			if len(args) == 2 {
   659→				return fmt.Sprintf(`fvx_concat(%s,%s)`, args[0], args[1])
   660→			}
   661→		case "str_sub":
   662→			if len(args) == 3 {
   663→				return fmt.Sprintf(`fvx_substr(%s,%s,%s)`, args[0], args[1], args[2])
   664→			}
   665→		case "str_from_char":
   666→			if len(args) == 1 {
   667→				return fmt.Sprintf(`fvx_from_char(%s)`, args[0])
   668→			}
   669→		case "int_to_str":
   670→			if len(args) == 1 {
   671→				return fmt.Sprintf(`fvx_int_to_str(%s)`, args[0])
   672→			}
   673→		case "read_file":
   674→			if len(args) == 1 {
   675→				return fmt.Sprintf(`fvx_read_file(%s)`, args[0])
   676→			}
   677→		}
   678→	}
   679→
   680→	return fmt.Sprintf("%s(%s)", fn, strings.Join(args, ", "))
