   692→	case "f64":
   693→		return fmt.Sprintf(`printf("%%f\n", %s)`, argStr)
   694→	case "string":
   695→		return fmt.Sprintf(`printf("%%s\n", %s)`, argStr)
   696→	case "bool":
   697→		return fmt.Sprintf(`printf("%%s\n", %s ? "true" : "false")`, argStr)
   698→	case "none":
   699→		return `printf("none\n")`
   700→	default:
   701→		// Default to i64
   702→		return fmt.Sprintf(`printf("%%lld\n", %s)`, argStr)
   703→	}
   704→}
