   821→// inferTypeFromExpression infers C type from AST expression
   822→func (g *Generator) inferTypeFromExpression(expr ast.Expression) string {
   823→	switch e := expr.(type) {
   824→	case *ast.IntegerLiteral:
   825→		return "long long"
   826→	case *ast.FloatLiteral:
   827→		return "double"
   828→	case *ast.StringLiteral:
   829→		return "char*"
   830→	case *ast.BoolLiteral:
   831→		return "bool"
   832→	case *ast.NoneLiteral:
   833→		return "void*"
   834→	case *ast.ArrayExpression:
   835→		if len(e.Elements) > 0 {
   836→			elemType := g.inferTypeFromExpression(e.Elements[0])
   837→			return fmt.Sprintf("%s*", elemType)
   838→		}
   839→		return "void*"
   840→	case *ast.StructExpression:
   841→		return e.Name // struct type name
   842→	case *ast.CallExpression:
   843→		if ident, ok := e.Function.(*ast.Identifier); ok {
   844→			// Builtin string functions
   845→			switch ident.Name {
   846→			case "str_concat", "str_sub", "str_from_char", "int_to_str", "read_file":
   847→				return "char*"
   848→			case "str_eq":
   849→				return "bool"
   850→			case "str_len", "str_at", "len", "abs", "min", "max", "to_int":
   851→				return "long long"
   852→			case "to_float":
   853→				return "double"
   854→			}
   855→			// Check extern func return types
   856→			if retType, exists := g.externFuncTypes[ident.Name]; exists {
   857→				if retType == "f64" {
   858→					return "double"
   859→				} else if retType == "i64" {
   860→					return "long long"
   861→				} else if retType == "string" {
   862→					return "char*"
   863→				} else if retType == "bool" {
   864→					return "bool"
   865→				}
   866→				return retType
   867→			}
   868→			// Check registered function return types
   869→			if retType, exists := g.funcReturnTypes[ident.Name]; exists {
   870→				return retType
   871→			}
   872→		}
   873→		return "long long" // Default for regular function calls
   874→	case *ast.BinaryExpression:
   875→		// If either operand is double, result is double
   876→		leftType := g.inferTypeFromExpression(e.Left)
   877→		rightType := g.inferTypeFromExpression(e.Right)
   878→		if leftType == "double" || rightType == "double" {
   879→			return "double"
   880→		}
   881→		return "long long"
   882→	default:
   883→		// Default to long long for unknown types
   884→		return "long long"
   885→	}
   886→}
