// arrayElemCType returns the C type for an FV array element type name
func (g *Generator) arrayElemCType(elemTypeName string) string {
	switch elemTypeName {
	case "i64":
		return "long long"
	case "f64":
		return "double"
	case "string":
		return "char*"
	case "bool":
		return "bool"
	default:
		return "long long"
	}
}

