static char* fvx_substr(const char* s, long long start, long long len) {
  long long slen = (long long)strlen(s);
  if(start<0) start=0; if(start>slen) start=slen;
  if(len<0) len=0; if(start+len>slen) len=slen-start;
  char* r = (char*)malloc(len+1); memcpy(r,s+start,len); r[len]=0; return r;
}
static char* fvx_from_char(long long c) {
  char* r = (char*)malloc(2); r[0]=(char)c; r[1]=0; return r;
