static char* fvx_read_file(const char* path) {
  FILE* f=fopen(path,"r"); if(!f) return strdup("");
  fseek(f,0,SEEK_END); long sz=ftell(f); rewind(f);
  char* buf=(char*)malloc(sz+1); fread(buf,1,sz,f); buf[sz]=0; fclose(f); return buf;
}




